(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20+Math.cos(y*0.013-t*0.18)*14+Math.sin((x+y)*0.008+t*0.12)*10;
  const w1y = Math.cos(y*0.02-t*0.22)*18+Math.sin(x*0.015+t*0.3)*12+Math.cos((x-y)*0.009-t*0.15)*8;
  const wx = Math.sin((x+w1x)*0.015+t*0.2)*12+Math.cos((y+w1y)*0.012-t*0.15)*8;
  const wy = Math.cos((y+w1y)*0.017-t*0.18)*11+Math.sin((x+w1x)*0.013+t*0.25)*7;
  const sx = x+w1x+wx, sy = y+w1y+wy;
  const src = [
    [140+Math.sin(t*0.5)*90,70+Math.cos(t*0.35)*40,0.07,0.11,1.8,0.9],
    [340+Math.cos(t*0.45)*80,80+Math.sin(t*0.55)*35,0.09,0.06,1.5,1.2],
    [240+Math.sin(t*0.3+2)*120,120+Math.cos(t*0.4+1)*70,0.055,0.09,2.1,0.7],
    [100+Math.cos(t*0.7+1)*70,170+Math.sin(t*0.5+3)*50,0.1,0.08,1.3,1.4],
    [380+Math.sin(t*0.35+4)*80,50+Math.cos(t*0.8+2)*60,0.065,0.12,2.4,0.6],
    [200+Math.cos(t*0.3+5)*100,200+Math.sin(t*0.45)*70,0.08,0.07,1.7,1.1],
    [300+Math.sin(t*0.6+3)*60,140+Math.cos(t*0.5+4)*80,0.075,0.1,2.0,0.8],
    [60+Math.cos(t*0.4+2)*50,120+Math.sin(t*0.65+1)*60,0.085,0.065,1.6,1.3]
  ];
  let feed=0,kill=0,activ=0,inhib=0;
  for(const[sX,sY,f1,f2,sp1,sp2]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    feed+=Math.sin(d*f1-t*sp1)*Math.cos(d*f2*0.5-t*sp2*0.3);
    kill+=Math.cos(d*f1*0.8+t*sp1*0.5)*Math.sin(d*f2+t*sp2);
    activ+=Math.sin(d*f1*1.2-t*sp1*1.1)+Math.sin(d*f2*0.6-t*sp2*0.7)*0.7;
    inhib+=Math.cos(d*f1*0.9+t*sp1*0.6+1.2)+Math.sin(d*f2*1.1+t*sp2*0.8)*0.6;
  }
  feed/=8;kill/=8;activ/=8;inhib/=8;
  const bg1=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.035+t*0.95))/2;
  const bg2=Math.sin((sx+sy)*0.1+t*2.2)*0.25+Math.sin((sx-sy)*0.08-t*1.8)*0.25;
  const bg3=Math.sin(sx*0.06+sy*0.04+t*1.5)*Math.cos(sx*0.04-sy*0.05-t*1.2)*0.3;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3-t*1.3)+Math.sin(dist*0.035+ang*5-t*1.0)+Math.sin(dist*0.06-ang*2+t*0.8)*0.5)*0.3;
  const diff=activ-inhib*0.65;
  const react=Math.tanh((diff+feed*0.4+bg*0.25+spiral)*2.0);
  const killRate=Math.tanh((kill*0.5-feed*0.3+bg*0.2)*1.5);
  let minD=999,minD2=999;
  for(let i=0;i<8;i++){
    const vx=60+((i*67+Math.sin(t*0.3+i*1.7)*40)%400);
    const vy=30+((i*53+Math.cos(t*0.25+i*2.1)*30)%190);
    const d=Math.sqrt((sx-vx)**2+(sy-vy)**2);
    if(d<minD){minD2=minD;minD=d;}else if(d<minD2){minD2=d;}
  }
  const cell=Math.tanh((minD2-minD)*0.15-0.5)*0.35;
  const contour=Math.pow(Math.abs(Math.sin(react*Math.PI*3)),8)*0.15;
  const blend=react*0.6+cell*0.2+killRate*0.15+contour*0.05;
  const v=blend*0.5+0.5;
  const pal=[[5,12,55],[10,45,95],[15,85,120],[20,130,135],[60,165,120],[160,185,80],[220,175,55],[215,130,65],[195,80,75],[155,45,70],[90,25,65],[40,15,55],[5,12,55]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const glow=Math.pow(Math.max(0,react),3)*0.4;
  const lum=0.75+Math.sin(react*Math.PI)*0.2+glow;
  const edge=Math.abs(react)>0.75?1.12:1.0;
  const breathe=1.0+Math.sin(t*0.4)*0.03;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*breathe)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*breathe)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*breathe)|0
  ];
}
